import { useMemo, useState } from "react";
import Ionicons from "@expo/vector-icons/Ionicons";
import { useQuery } from "@tanstack/react-query";
import { useRouter } from "expo-router";
import { Image, Pressable, RefreshControl, ScrollView, StyleSheet, Text, View } from "react-native";
import { API_BASE_URL, apiFetch } from "@/api";
import { useMobileBranding } from "@/branding";
import { Button, EmptyState, ErrorState, Header, Screen } from "@/components";
import { colors, shadow } from "@/theme";
import type { HallOfFame, HallPlayer } from "@/types";
import { AchievementBadge } from "@/achievement-badge";
import { CollectiveBadge } from "@/collective-badge";
import { HallRecordBadge } from "@/hall-record-badge";
import { mobilePlayerPhotoUrl } from "@/player-photo-url";

export default function HallOfFameScreen() {
  const router = useRouter(), { palette } = useMobileBranding(), [season, setSeason] = useState<number | "all">("all");
  const query = useQuery({ queryKey: ["hall-of-fame"], queryFn: ({ signal }) => apiFetch<HallOfFame>("/api/hall-of-fame", { signal }) });
  const classes = useMemo(() => season === "all" ? query.data?.classes || [] : query.data?.classes.filter(item => item.seasonNumber === season) || [], [query.data?.classes, season]);
  return <Screen><Header eyebrow="MEMÓRIA DA PELADA" title="Hall da Fama"/><ScrollView contentContainerStyle={styles.content} refreshControl={<RefreshControl refreshing={query.isRefetching} onRefresh={() => void query.refetch()} tintColor={palette.green}/>}>
    <Button title="← Meu card" variant="secondary" onPress={() => router.back()}/>
    <View style={[styles.intro, { borderColor: palette.green }]}><View style={[styles.emblem, { borderColor: palette.green }]}><Text style={[styles.emblemStar, { color: palette.green }]}>★</Text><Text style={[styles.emblemText, { color: palette.green }]}>HALL</Text></View><View style={styles.grow}><Text style={styles.title}>A história da nossa pelada</Text><Text style={styles.description}>Ídolos, classes anuais, recordes e atuações preservados pelos resultados oficiais.</Text></View></View>
    {query.isError ? <ErrorState message={query.error.message} retry={() => void query.refetch()}/> : null}
    {query.isPending ? <View style={styles.loading}><Text style={[styles.eyebrow, { color: palette.green }]}>ABRINDO AS PORTAS DO HALL…</Text></View> : null}
    {query.data ? <>
      <View style={styles.summary}>{[[query.data.summary.seasons,"Temporadas"],[query.data.summary.inductedPlayers,"Homenageados"],[query.data.summary.officialMatches,"Partidas"],[query.data.summary.records,"Recordes"]].map(([value,label]) => <View key={String(label)} style={styles.metric}><Text style={[styles.metricValue,{color:palette.green}]}>{value}</Text><Text style={styles.metricLabel}>{label}</Text></View>)}</View>
      <Section eyebrow="HISTÓRIA COLETIVA" title="Marcos da nossa pelada" description="Metas compartilhadas e acontecimentos confirmados pelos resultados oficiais." color={palette.green}/>
      <View style={styles.communityProgress}>{(query.data.collectiveProgress||[]).map(item=><View style={styles.communityGoal} key={item.id}><View style={styles.communityGoalHead}><CollectiveBadge kind={item.kind} icon={item.icon} title={item.title} size={48}/><View style={styles.grow}><Text style={[styles.eyebrow,{color:palette.green}]}>{item.scope==="SEASON"?"META DA TEMPORADA":"META HISTÓRICA"}</Text><Text style={styles.communityGoalTitle}>{item.title}</Text><Text style={styles.description}>{item.description}</Text></View><Text style={[styles.communityPercent,{color:palette.green}]}>{item.percent}%</Text></View><View style={styles.communityTrack}><View style={[styles.communityTrackValue,{width:`${item.percent}%`,backgroundColor:palette.green}]}/></View><Text style={styles.communityCount}>{item.current} de {item.target}</Text></View>)}</View>
      {(query.data.collectiveMilestones||[]).length ? query.data.collectiveMilestones.map(item=><Pressable disabled={!item.separationId} onPress={()=>item.separationId&&router.push({pathname:"/separations/[id]",params:{id:item.separationId,tab:"result"}})} style={styles.communityMilestone} key={item.id}><CollectiveBadge kind={item.kind} icon={item.icon} title={item.title} size={54}/><View style={styles.grow}><Text style={[styles.eyebrow,{color:palette.green}]}>{dateLabel(item.achievedAt)}{item.seasonNumber?` · TEMPORADA ${item.seasonNumber}`:""}</Text><Text style={styles.momentTitle}>{item.title}</Text><Text style={styles.description}>{item.description}</Text>{item.separationId?<Text style={[styles.momentLink,{color:palette.green}]}>Rever partida →</Text>:null}</View></Pressable>) : <EmptyState title="História sendo construída" message="O primeiro marco coletivo aparecerá conforme a pelada avançar nas metas oficiais."/>}
      <Section eyebrow="GALERIA PRINCIPAL" title="Nomes eternizados" description="Ídolos da comunidade e líderes das temporadas encerradas." color={palette.green}/>
      {query.data.featured.length ? query.data.featured.map(entry => <View style={styles.featured} key={entry.id}><View style={styles.featuredTop}><Avatar player={entry.player} size={78}/><View style={styles.grow}><Text style={[styles.eyebrow,{color:palette.green}]}>{entry.title.toUpperCase()} · CLASSE {entry.inductedSeason}</Text><Text style={styles.featuredName}>{entry.player.displayName}</Text><Text style={styles.description}>{entry.reason}</Text></View></View><View style={styles.badges}>{entry.badges.map(value => <Text key={value} style={[styles.badge,{color:palette.green,borderColor:palette.green}]}>{value}</Text>)}</View><View style={styles.playerMetrics}>{[[entry.totals.games,"Jogos"],[entry.totals.wins,"Vitórias"],[entry.totals.goals,"Gols"],[entry.totals.assists,"Assist."]].map(([value,label]) => <View key={String(label)} style={styles.playerMetric}><Text style={[styles.playerMetricValue,{color:palette.green}]}>{value}</Text><Text style={styles.playerMetricLabel}>{label}</Text></View>)}</View></View>) : <EmptyState title="Galeria em formação" message="Os primeiros nomes aparecerão após o encerramento de uma temporada ou dez reconhecimentos sociais."/>}
      <Section eyebrow="CLASSES ANUAIS" title="A história por temporada" description="Cada pódio encerrado permanece preservado." color={palette.green}/>
      <ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={styles.filters}><Filter active={season==="all"} label="Todas" onPress={()=>setSeason("all")} color={palette.green}/>{query.data.availableSeasons.map(value=><Filter key={value} active={season===value} label={`Temporada ${value}`} onPress={()=>setSeason(value)} color={palette.green}/>)}</ScrollView>
      {classes.length ? classes.map(item => <View style={styles.hallClass} key={item.seasonNumber}><View style={[styles.classHead,{backgroundColor:`${palette.green}12`}]}><Text style={[styles.eyebrow,{color:palette.green}]}>CLASSE</Text><Text style={styles.classNumber}>{item.seasonNumber}</Text><Text style={styles.classDate}>{dateLabel(item.endedAt)}</Text></View>{item.members.map(member => <View style={styles.classMember} key={`${item.seasonNumber}:${member.player.id}`}><Text style={styles.medal}>{member.medal}</Text><Avatar player={member.player} size={44}/><View style={styles.grow}><Text style={[styles.eyebrow,{color:palette.green}]}>{member.title.toUpperCase()}</Text><Text style={styles.memberName}>{member.player.displayName}</Text><Text style={styles.memberDetail}>{member.totals.games} jogos · {member.totals.wins} vitórias</Text></View></View>)}</View>) : <EmptyState title="Classe ainda não encerrada" message="O pódio aparecerá quando a temporada for consolidada."/>}
      <Section eyebrow="ALA DOS RECORDES" title="Donos das maiores marcas" description="As placas acompanham todo o histórico oficial." color={palette.green}/>
      <View style={styles.records}>{query.data.records.map(record => <View style={styles.record} key={record.id}><HallRecordBadge id={record.id} icon={record.icon} title={record.title}/><Text style={styles.recordTitle}>{record.title}</Text><Text style={[styles.recordValue,{color:palette.green}]}>{record.value}</Text><Text style={styles.recordUnit}>{record.unit}</Text><View style={styles.recordPlayers}>{record.players.slice(0,2).map(player=><View style={styles.recordPlayer} key={player.id}><Avatar player={player} size={25}/><Text numberOfLines={1} style={styles.recordPlayerName}>{player.displayName}</Text></View>)}</View></View>)}</View>
      <Section eyebrow="MOMENTOS ETERNOS" title="Feitos que viraram história" description="Conquistas raras ligadas à rodada em que aconteceram." color={palette.green}/>
      {query.data.moments.length ? query.data.moments.map(moment => <Pressable disabled={!moment.matchId} onPress={()=>moment.matchId&&router.push({pathname:"/separations/[id]",params:{id:moment.matchId}})} style={styles.moment} key={moment.id}><AchievementBadge id={moment.id} icon={moment.icon} title={moment.title} size={50}/><View style={styles.grow}><Text style={styles.momentDate}>{dateLabel(moment.achievedAt)}</Text><Text style={styles.momentTitle}>{moment.title}</Text><Text style={[styles.momentPlayer,{color:palette.green}]}>{moment.player.displayName}</Text><Text style={styles.description}>{moment.description}</Text>{moment.matchId?<Text style={[styles.momentLink,{color:palette.green}]}>Rever partida →</Text>:null}</View></Pressable>) : <EmptyState title="Os grandes momentos virão" message="Os feitos raros aparecerão conforme forem conquistados."/>}
    </> : null}
  </ScrollView></Screen>;
}

function Section({eyebrow,title,description,color}:{eyebrow:string;title:string;description:string;color:string}) { return <View style={styles.sectionTitle}><Text style={[styles.eyebrow,{color}]}>{eyebrow}</Text><Text style={styles.title}>{title}</Text><Text style={styles.description}>{description}</Text></View>; }
function Filter({active,label,onPress,color}:{active:boolean;label:string;onPress():void;color:string}) { return <Pressable accessibilityRole="button" accessibilityState={{selected:active}} onPress={onPress} style={[styles.filter,active&&{backgroundColor:color,borderColor:color}]}><Text style={[styles.filterText,active&&styles.filterTextActive]}>{label}</Text></Pressable>; }
function Avatar({player,size}:{player:HallPlayer;size:number}) {
  const [failedUri,setFailedUri]=useState<string|null>(null);
  const uri=mobilePlayerPhotoUrl(player.photoUrl,API_BASE_URL);
  const dimensions={width:size,height:size,borderRadius:size/2};
  return uri&&uri!==failedUri?<Image source={{uri}} accessibilityLabel={`Foto de ${player.displayName}`} resizeMode="cover" onError={()=>setFailedUri(uri)} style={[styles.avatar,dimensions]}/>:<View accessible accessibilityLabel={player.displayName} style={[styles.avatar,dimensions,styles.avatarFallback]}><Ionicons name="person" size={size*.46} color={colors.muted}/></View>;
}
function dateLabel(value:string){const date=new Date(`${value.slice(0,10)}T12:00:00`);return Number.isNaN(date.getTime())?value:date.toLocaleDateString("pt-BR")}

const styles=StyleSheet.create({
  content:{padding:16,paddingBottom:34,gap:14},
  grow:{flex:1,minWidth:0},
  intro:{flexDirection:"row",alignItems:"center",gap:14,borderWidth:1,borderRadius:20,backgroundColor:colors.card,padding:17,...shadow},
  emblem:{width:76,height:76,alignItems:"center",justifyContent:"center",borderWidth:2,borderRadius:38},emblemStar:{fontSize:23,fontWeight:"900"},emblemText:{fontSize:12,fontWeight:"900",letterSpacing:1},
  title:{color:colors.text,fontSize:23,lineHeight:28,fontWeight:"900"},description:{color:colors.muted,fontSize:12,lineHeight:18},eyebrow:{fontSize:9,fontWeight:"900",letterSpacing:1.1},loading:{minHeight:120,alignItems:"center",justifyContent:"center"},
  summary:{flexDirection:"row",flexWrap:"wrap",gap:8},metric:{flexGrow:1,flexBasis:"46%",minHeight:78,justifyContent:"center",borderWidth:1,borderColor:colors.border,borderRadius:14,backgroundColor:colors.card,padding:13},metricValue:{fontSize:26,fontWeight:"900"},metricLabel:{marginTop:3,color:colors.muted,fontSize:9,fontWeight:"800",textTransform:"uppercase"},
  communityProgress:{gap:8},communityGoal:{gap:8,borderWidth:1,borderColor:colors.border,borderRadius:14,backgroundColor:colors.card,padding:13},communityGoalHead:{flexDirection:"row",alignItems:"center",gap:9},communityIcon:{fontSize:23},communityGoalTitle:{color:colors.text,fontSize:14,fontWeight:"900"},communityPercent:{fontSize:17,fontWeight:"900"},communityTrack:{height:8,overflow:"hidden",borderRadius:99,backgroundColor:"#E3EBE6"},communityTrackValue:{height:"100%",borderRadius:99},communityCount:{color:colors.muted,fontSize:8,fontWeight:"800",textAlign:"right"},communityMilestone:{flexDirection:"row",gap:11,borderWidth:1,borderColor:colors.border,borderRadius:15,backgroundColor:colors.card,padding:14},communityMilestoneIcon:{width:48,height:48,alignItems:"center",justifyContent:"center",borderWidth:1,borderRadius:24},
  sectionTitle:{gap:4,marginTop:8},featured:{gap:13,borderWidth:1,borderColor:colors.border,borderRadius:18,backgroundColor:colors.card,padding:17,...shadow},featuredTop:{flexDirection:"row",alignItems:"center",gap:13},avatar:{borderWidth:2,borderColor:colors.border,backgroundColor:"#E9EFEB"},avatarFallback:{alignItems:"center",justifyContent:"center"},featuredName:{color:colors.text,fontSize:21,fontWeight:"900",marginVertical:2},badges:{flexDirection:"row",flexWrap:"wrap",gap:6},badge:{borderWidth:1,borderRadius:99,paddingHorizontal:8,paddingVertical:5,fontSize:8,fontWeight:"800"},
  playerMetrics:{flexDirection:"row",overflow:"hidden",borderWidth:1,borderColor:colors.border,borderRadius:12},playerMetric:{flex:1,minWidth:0,paddingVertical:10,paddingHorizontal:3,borderRightWidth:1,borderRightColor:colors.border},playerMetricValue:{color:colors.green,fontSize:18,fontWeight:"900",textAlign:"center"},playerMetricLabel:{marginTop:2,color:colors.muted,fontSize:8,fontWeight:"800",textAlign:"center",textTransform:"uppercase"},
  filters:{gap:8,paddingRight:16},filter:{minHeight:40,justifyContent:"center",borderWidth:1,borderColor:colors.border,borderRadius:99,backgroundColor:colors.card,paddingHorizontal:14},filterText:{color:colors.text,fontSize:11,fontWeight:"800"},filterTextActive:{color:"#FFFFFF"},
  hallClass:{overflow:"hidden",borderWidth:1,borderColor:colors.border,borderRadius:17,backgroundColor:colors.card},classHead:{alignItems:"center",padding:14,borderBottomWidth:1,borderBottomColor:colors.border},classNumber:{color:colors.text,fontSize:32,fontWeight:"900"},classDate:{color:colors.muted,fontSize:9},classMember:{flexDirection:"row",alignItems:"center",gap:10,padding:14,borderBottomWidth:1,borderBottomColor:colors.border},medal:{fontSize:22},memberName:{color:colors.text,fontSize:14,fontWeight:"900"},memberDetail:{marginTop:2,color:colors.muted,fontSize:10},
  records:{flexDirection:"row",flexWrap:"wrap",gap:8},record:{flexGrow:1,flexBasis:"46%",minHeight:225,borderWidth:1,borderColor:colors.border,borderRadius:15,backgroundColor:colors.card,padding:14},recordTitle:{marginTop:6,color:colors.muted,fontSize:9,fontWeight:"900",textTransform:"uppercase"},recordValue:{marginTop:3,fontSize:31,fontWeight:"900"},recordUnit:{color:colors.muted,fontSize:9},recordPlayers:{gap:6,marginTop:"auto",paddingTop:11,borderTopWidth:1,borderTopColor:colors.border},recordPlayer:{flexDirection:"row",alignItems:"center",gap:6},recordPlayerName:{flex:1,color:colors.text,fontSize:9,fontWeight:"800"},
  moment:{flexDirection:"row",gap:12,borderWidth:1,borderColor:colors.border,borderRadius:15,backgroundColor:colors.card,padding:14},momentDate:{color:colors.muted,fontSize:8,fontWeight:"700"},momentTitle:{marginTop:2,color:colors.text,fontSize:17,fontWeight:"900"},momentPlayer:{marginTop:2,fontSize:11,fontWeight:"900"},momentLink:{marginTop:7,fontSize:10,fontWeight:"900"},
});
